using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

builder.Services.AddChatClient(pipeline => pipeline
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteService>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about the " +
    "user's topic. Take notes on key findings using the take_note tool. After gathering " +
    "enough information (at least 3 searches), synthesize your notes into a final summary.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "recent advances in quantum computing 2026";

Console.WriteLine($"Researching: {topic}\n");

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = [.. AIFunctionFactory.Create(researchTools.WebSearch),
             .. AIFunctionFactory.Create(researchTools.TakeNote)],
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Notes Collected ---");
var noteService = host.Services.GetRequiredService<NoteService>();
foreach (var note in noteService.GetNotes())
{
    Console.WriteLine($"• {note}");
}

// --- Services ---

public sealed class NoteService
{
    private readonly List<string> _notes = [];

    public void Add(string note) => _notes.Add(note);
    public IReadOnlyList<string> GetNotes() => _notes;
}

public sealed class ResearchTools(NoteService noteService)
{
    [Description("Search the web for information on a query. Returns search result snippets.")]
    public Task<string> WebSearch([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (e.g., Bing Search API) for production use.
        var results = $"""
            Search results for: "{query}"

            1. [Research Paper] Key findings related to {query} show significant progress 
               in the field with multiple breakthroughs reported in recent studies.

            2. [News Article] Experts report that {query} has seen major developments,
               with new techniques achieving unprecedented performance benchmarks.

            3. [Industry Report] Market analysis indicates growing investment in {query},
               with applications expanding across healthcare, finance, and technology sectors.
            """;

        Console.WriteLine($"  [🔍 Searching: \"{query}\"]\n");
        return Task.FromResult(results);
    }

    [Description("Take a note to record an important finding from research.")]
    public string TakeNote(
        [Description("The note content to save")] string content,
        [Description("Source or context for the note")] string source)
    {
        noteService.Add($"[{source}] {content}");
        Console.WriteLine($"  [📝 Note taken: \"{content[..Math.Min(60, content.Length)]}...\"]\n");
        return $"Note saved: {content}";
    }
}

